INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content_raw, content_html, category, seo_desc, image_key, image_source, image_alt, published, date, created_at, updated_at)
VALUES ('post_1778645846369', '10-000-fuer-ein-ebike-das-ist-ganz-normal', '🚲 10.000€ Für ein eBike? Das ist ganz normal!', 'Ein eBike für 4.000€ klingt nach einer klaren Sache. Doch wer die Gesamtkosten über 10 Jahre durchrechnet, landet schnell bei 10.000€ oder mehr. Versicherung, Verschleißteile, Service und Akku – das summiert sich. Ich zeige dir, was dein eBike wirklich kostet und ob eine eBike Versicherung am Ende günstiger ist als alles selbst zu zahlen.', 'Tatsächlich ist es genau so. Denn neben den Anschaffungskosten müssen auch 

- Zubehör und Helm
- Servicekosten
- Kosten für Verschleißteile
- Software Updates
- Eine Fahrradversicherung
und ein
- Ersatz- bzw. Zusatzakku
eingerechnet werden. 

🥇 Gehen wir mal von folgendem aus:
Ein aktuelles eBike kostet schnell mal 4.000€. Dazu benötigen wir in jedem Fall:
- ein Schloss (ca. 100€)
- einen Helm (ca. 80€)
Damit sind wir bei 4.180€ 

Ab hier rechnen wir die Kosten für die durchschnittliche Lebensdauer eines Fahrrades. Also 10 Jahre. 

- Nehmen wir eine "Wertgarantie" Versicherung dazu. Die kostet pro Monat 16,50€. Das sind ca. 1.980€ in 10 Jahren. Gut an dieser Variante ist, dass diese Versicherung den jährlichen Service, Software Updates, Verschleißteile, Diebstahl und Vandalismusschäden mit abdeckt. Weitere Kosten sind also nicht zu erwarten. 

- Diese Versicherung bietet einen optionalen Akkuschutz an. Dieser kostet 5€ im Monat. Also 600€ in 10 Jahren. 

-》 Wir sind bei dieser Variante also bei 6.760€ | 676€ pro Jahr. 

🥈 Tun wir jetzt mal so, als würden wir uns gegen eine Wertgarantie Versicherung entscheiden. Dann hätten wir: 

- das eBike, einen zweiten Akku, den Helm und ein Schloss kaufen wir für 5.000€. 

Im Jahr kommen dazu:
- 2 Paar Bremsbeläge 60€ + 40€ Montage
- ein Rad Service + Software Update 150€
- eine neue Kette 45€
Zusammen: 300€ pro Jahr. Also 3.000€ in 10 Jahren. 

Alle 2 Jahre:
- eine Kassette 150€
- Ein Reifen (hinten oder vorne) 45€
- zusätzliche Reparaturen durch Unfall oder Vandalismus 200€
Zusammen: 400€ alle 2 Jahre. Also 2.000€ in 10 Jahren. 

-》 Das wären dann 10.000€ | 1.000€ pro Jahr 

FAZIT: Diese Milchmädchenrechnung zeigt, dass ein eBike nicht nur das kostet, was auf dem Etikett steht. Es kostet eine ganze Menge mehr. Und dessen sollte man sich bewusst sein. 

Zudem würde ich in jedem Fall versuchen das Bike mit einer entsprechenden Versicherung zu schützen. Das spart tatsächlich sehr viel Geld. 


⚠️ DISCLAIMER: Ich habe keine Partnerschaft mit der "Wertgarantie". Diese Versicherung ist mir lediglich geläufig, weil ich diese meinen Kunden häufig als Sinnvollen Zusatz angeboten habe.', '<p>Tatsächlich ist es genau so. Denn neben den Anschaffungskosten müssen auch</p>
<p>- Zubehör und Helm<br>- Servicekosten<br>- Kosten für Verschleißteile<br>- Software Updates<br>- Eine Fahrradversicherung<br>und ein<br>- Ersatz- bzw. Zusatzakku<br>eingerechnet werden.</p>
<p>🥇 Gehen wir mal von folgendem aus:<br>Ein aktuelles eBike kostet schnell mal 4.000€. Dazu benötigen wir in jedem Fall:<br>- ein Schloss (ca. 100€)<br>- einen Helm (ca. 80€)<br>Damit sind wir bei 4.180€</p>
<p>Ab hier rechnen wir die Kosten für die durchschnittliche Lebensdauer eines Fahrrades. Also 10 Jahre.</p>
<ul><li>Nehmen wir eine &quot;Wertgarantie&quot; Versicherung dazu. Die kostet pro Monat 16,50€. Das sind ca. 1.980€ in 10 Jahren. Gut an dieser Variante ist, dass diese Versicherung den jährlichen Service, Software Updates, Verschleißteile, Diebstahl und Vandalismusschäden mit abdeckt. Weitere Kosten sind also nicht zu erwarten.</li></ul>
<ul><li>Diese Versicherung bietet einen optionalen Akkuschutz an. Dieser kostet 5€ im Monat. Also 600€ in 10 Jahren.</li></ul>
<p>-》 Wir sind bei dieser Variante also bei 6.760€ | 676€ pro Jahr.</p>
<p>🥈 Tun wir jetzt mal so, als würden wir uns gegen eine Wertgarantie Versicherung entscheiden. Dann hätten wir:</p>
<ul><li>das eBike, einen zweiten Akku, den Helm und ein Schloss kaufen wir für 5.000€.</li></ul>
<p>Im Jahr kommen dazu:<br>- 2 Paar Bremsbeläge 60€ + 40€ Montage<br>- ein Rad Service + Software Update 150€<br>- eine neue Kette 45€<br>Zusammen: 300€ pro Jahr. Also 3.000€ in 10 Jahren.</p>
<p>Alle 2 Jahre:<br>- eine Kassette 150€<br>- Ein Reifen (hinten oder vorne) 45€<br>- zusätzliche Reparaturen durch Unfall oder Vandalismus 200€<br>Zusammen: 400€ alle 2 Jahre. Also 2.000€ in 10 Jahren.</p>
<p>-》 Das wären dann 10.000€ | 1.000€ pro Jahr</p>
<p>FAZIT: Diese Milchmädchenrechnung zeigt, dass ein eBike nicht nur das kostet, was auf dem Etikett steht. Es kostet eine ganze Menge mehr. Und dessen sollte man sich bewusst sein.</p>
<p>Zudem würde ich in jedem Fall versuchen das Bike mit einer entsprechenden Versicherung zu schützen. Das spart tatsächlich sehr viel Geld.</p>
<p>⚠️ DISCLAIMER: Ich habe keine Partnerschaft mit der &quot;Wertgarantie&quot;. Diese Versicherung ist mir lediglich geläufig, weil ich diese meinen Kunden häufig als Sinnvollen Zusatz angeboten habe.</p>', 'Erfahrung', 'Ein eBike kostet mehr als der Kaufpreis. Wir rechnen durch, was Versicherung, Service und Verschleiß über 10 Jahre wirklich kosten – und was sich lohnt.', 'blogimages/kein_geld_mehr_2048.webp', 'static', '🚲 10.000€ Für ein eBike? Das ist ganz normal!', 1, '2026-05-13', '2026-05-13T00:00:00.000Z', '2026-05-13T00:00:00.000Z');

INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content_raw, content_html, category, seo_desc, image_key, image_source, image_alt, published, date, created_at, updated_at)
VALUES ('post_1778528572482', 'wichtiger-rueckruf-cube-e-bike-besitzer-aufgepasst', '⚠️ WICHTIGER RÜCKRUF – CUBE E-BIKE BESITZER AUFGEPASST', 'Cube ruft E-Bike-Modelle des MJ 2026 zurück. Defekte Kurbel kann zum Sturz führen. Jetzt Rahmennummer prüfen & kostenlosen Austausch beim Händler holen.', 'Cube hat am 08.05.2026 einen Produktsicherheitsrückruf für bestimmte E-Bike-Modelle des Modelljahres 2026 gestartet.

🔧 Das Problem: Bei den ACID Carbon Hybrid Kurbelarmen 2026 kann der Aluminium-Gewindeeinsatz in der Pedalaufnahme plötzlich ausbrechen. Das kann zu einem Sturz führen.

Was tun, wenn du ein Cube E-Bike 2026 hast?
👉 Sofort aufhören zu fahren
👉 Rahmennummer (WOW-Nummer) am Tretlager prüfen
👉 Rahmennummer im Cube-Tool auf cube.eu/rueckrufe checken
👉 Fachhändler kontaktieren → kostenloser Austausch

Betroffen sind Modelle
- Stereo Hybrid ONE44/ONE77 HPC,
- AMS Hybrid ONE44
- Reaction Hybrid SLT
- Kathmandu Hybrid C:62
- Nuroad Hybrid C:62 — alle MJ 2026, ausgeliefert vor dem 08.05.2026.

Der Austausch ist kostenlos und läuft ausschließlich über autorisierte Cube Händler. Als Ausgleich für den dauerhaften Wechsel auf eine Alu-Kurbel gibt''s ein Frontlicht im Wert von 149,95 € dazu.

Den genauen Rückruf-Link findest du im ersten Kommentar unter diesem Beitrag. Wenn du dir unsicher bist... einfach kurz kommentieren, ich helfe gern weiter.

#cuberückruf #ebike #rückruf #radlhias', '<p>Cube hat am 08.05.2026 einen Produktsicherheitsrückruf für bestimmte E-Bike-Modelle des Modelljahres 2026 gestartet.</p>
<p>🔧 Das Problem: Bei den ACID Carbon Hybrid Kurbelarmen 2026 kann der Aluminium-Gewindeeinsatz in der Pedalaufnahme plötzlich ausbrechen. Das kann zu einem Sturz führen.</p>
<p>Was tun, wenn du ein Cube E-Bike 2026 hast?<br>👉 Sofort aufhören zu fahren<br>👉 Rahmennummer (WOW-Nummer) am Tretlager prüfen<br>👉 Rahmennummer im Cube-Tool auf cube.eu/rueckrufe checken<br>👉 Fachhändler kontaktieren → kostenloser Austausch</p>
<p>Betroffen sind Modelle<br>- Stereo Hybrid ONE44/ONE77 HPC,<br>- AMS Hybrid ONE44<br>- Reaction Hybrid SLT<br>- Kathmandu Hybrid C:62<br>- Nuroad Hybrid C:62 — alle MJ 2026, ausgeliefert vor dem 08.05.2026.</p>
<p>Der Austausch ist kostenlos und läuft ausschließlich über autorisierte Cube Händler. Als Ausgleich für den dauerhaften Wechsel auf eine Alu-Kurbel gibt&#39;s ein Frontlicht im Wert von 149,95 € dazu.</p>
<p>Den genauen Rückruf-Link findest du im ersten Kommentar unter diesem Beitrag. Wenn du dir unsicher bist... einfach kurz kommentieren, ich helfe gern weiter.</p>
<p>#cuberückruf #ebike #rückruf #radlhias</p>', 'Technik', 'Cube E-Bike Rückruf 2026: Defekte Kurbel Sturzgefahr. Jetzt WOW-Nummer prüfen, Händler kontaktieren & kostenlosen Austausch + Frontlicht (149,95 €) sichern.', 'blogimages/acid_carbon_kurbel_rueckruf.webp', 'static', '⚠️ WICHTIGER RÜCKRUF – CUBE E-BIKE BESITZER AUFGEPASST', 1, '2026-05-11', '2026-05-11T00:00:00.000Z', '2026-05-11T00:00:00.000Z');

INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content_raw, content_html, category, seo_desc, image_key, image_source, image_alt, published, date, created_at, updated_at)
VALUES ('post_1778500938584', 'sollte-jeder-ein-ebike-fahren-duerfen', '🚲 Sollte jeder ein eBike fahren dürfen?', 'Sollte wirklich jeder ein eBike fahren dürfen? Radl Hias stellt eine unbequeme Frage, die weder Hersteller noch Händler gerne hören: Wird beim eBike-Verkauf Verantwortung gegenüber älteren oder körperlich eingeschränkten Käufern übernommen – oder zählt nur der Abschluss? Ein ehrlicher Blick auf Sicherheit, Reaktionsfähigkeit und die Frage, was verantwortungsvoller Fahrradhandel wirklich bedeutet.', 'Ich würde nicht die Instanz sein wollen, die das entscheidet. Aber wie ist es mit der Sicherheit?

⛑️ Sicherheit für die Fahrer, ebenso wie die Sicherheit anderer. Ist es wirklich gut, wenn jeder motorisiert unterwegs ist? Ganz unabhängig von seiner geistigen und körperlichen Fitness. Ganz unabhängig auch von seiner Reaktionsfähigkeit und vielleicht sogar von den körperlichen Einschränkungen, die er hat.

Ein eBike zu fahren bedeutet... immer schnell zu fahren. In gewissen Situationen schneller reagieren zu müssen und das dauerhaft. Ich möchte niemanden diskriminieren oder seine Tauglichkeit absprechen. Aber es ist nachgewiesen und logisch, dass Radfahrer höheren Alters anders reagieren, als ein 30 Jahre junger Mann (in der Blüte seines Lebens).

Und genau dieser Unterschied sollte im Verkauf, ebenso wie im Marketing der Hersteller eine Rolle spielen.
Warum nicht ein eBike entwickeln, das speziell für Damen und Herren des älteren Semesters abgestimmt wurde? Warum nicht den Mut haben und einem Kunden durch verantwortungsbewusste Argumentationen von einem eBike abraten und stattdessen zu einer Alternative raten?

Was das für eine Alternative sein könnte, werde ich mal in einem zukünftigen Post beleuchten.', '<p>Ich würde nicht die Instanz sein wollen, die das entscheidet. Aber wie ist es mit der Sicherheit?</p>
<p>⛑️ Sicherheit für die Fahrer, ebenso wie die Sicherheit anderer. Ist es wirklich gut, wenn jeder motorisiert unterwegs ist? Ganz unabhängig von seiner geistigen und körperlichen Fitness. Ganz unabhängig auch von seiner Reaktionsfähigkeit und vielleicht sogar von den körperlichen Einschränkungen, die er hat.</p>
<p>Ein eBike zu fahren bedeutet... immer schnell zu fahren. In gewissen Situationen schneller reagieren zu müssen und das dauerhaft. Ich möchte niemanden diskriminieren oder seine Tauglichkeit absprechen. Aber es ist nachgewiesen und logisch, dass Radfahrer höheren Alters anders reagieren, als ein 30 Jahre junger Mann (in der Blüte seines Lebens).</p>
<p>Und genau dieser Unterschied sollte im Verkauf, ebenso wie im Marketing der Hersteller eine Rolle spielen.<br>Warum nicht ein eBike entwickeln, das speziell für Damen und Herren des älteren Semesters abgestimmt wurde? Warum nicht den Mut haben und einem Kunden durch verantwortungsbewusste Argumentationen von einem eBike abraten und stattdessen zu einer Alternative raten?</p>
<p>Was das für eine Alternative sein könnte, werde ich mal in einem zukünftigen Post beleuchten.</p>', 'Meinung', 'Sollte jeder ein eBike fahren dürfen? Radl Hias fragt, was Händler und Hersteller beim Thema Sicherheit und Verantwortung gerne verschweigen.', 'blogimages/Oma_faehrt_ebike_2048.webp', 'static', '🚲 Sollte jeder ein eBike fahren dürfen?', 1, '2026-05-11', '2026-05-11T00:00:00.000Z', '2026-05-11T00:00:00.000Z');

INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content_raw, content_html, category, seo_desc, image_key, image_source, image_alt, published, date, created_at, updated_at)
VALUES ('post_1778176712986', 'ich-fahre-kein-ebike-aber-ich-verstehe-jeden-der-es-tut', '🚲 Ich fahre kein eBike. Aber ich verstehe jeden, der es tut.', 'In diesem Beitrag stelle ich klar, dass eBikes Sinn machen können und sich die Investition lohnt. Allerdings nicht für jeden.', 'Ich bin süße 45 Jahre jung 😅, bis auf mein Alters- Bäuchlein auch recht fit und ich habe kurze Wege. Und wenn ich mal längere Wege habe, dann weil ich mir diese ausgesucht habe. Für mich persönlich brauche ich keine Unterstützung auf dem Rad.

Ich weiß aber auch, dass meine Situation nicht auf alle Radfahrer zutrifft. Wer täglich 25 Kilometer zur Arbeit pendelt und trotzdem nicht verschwitzt ankommen will, dem gibt ein eBike echte Freiheit und Flexibilität.
Wer nach einer Knie-OP wieder mobil sein will. Wer in einer Stadt lebt und das Rad als ernsthaftes Transportmittel nutzt und nicht nur für einen Sonntagsausflug... All das sind auch für mich sehr gute Gründe für einen Motor am Rad.

🤔 Ein eBike kann mehr Lebensqualität bedeuten. Mehr Bewegung, weniger Auto, weniger Stress. Das ist nicht nichts.

In den nächsten Posts schaue ich mir aber auch an, was Händler und Hersteller beim Verkaufsgespräch gerne weglassen. Nicht um zu warnen... sondern damit du eine Entscheidung treffen kannst, die wirklich zu dir passt.', '<p>Ich bin süße 45 Jahre jung 😅, bis auf mein Alters- Bäuchlein auch recht fit und ich habe kurze Wege. Und wenn ich mal längere Wege habe, dann weil ich mir diese ausgesucht habe. Für mich persönlich brauche ich keine Unterstützung auf dem Rad.</p>
<p>Ich weiß aber auch, dass meine Situation nicht auf alle Radfahrer zutrifft. Wer täglich 25 Kilometer zur Arbeit pendelt und trotzdem nicht verschwitzt ankommen will, dem gibt ein eBike echte Freiheit und Flexibilität.<br>Wer nach einer Knie-OP wieder mobil sein will. Wer in einer Stadt lebt und das Rad als ernsthaftes Transportmittel nutzt und nicht nur für einen Sonntagsausflug... All das sind auch für mich sehr gute Gründe für einen Motor am Rad.</p>
<p>🤔 Ein eBike kann mehr Lebensqualität bedeuten. Mehr Bewegung, weniger Auto, weniger Stress. Das ist nicht nichts.</p>
<p>In den nächsten Posts schaue ich mir aber auch an, was Händler und Hersteller beim Verkaufsgespräch gerne weglassen. Nicht um zu warnen... sondern damit du eine Entscheidung treffen kannst, die wirklich zu dir passt.</p>', 'Meinung', 'Meinung und Einschätzung, wann eine Investition in ein eBike bzw. Elektrofahrrad lohnt.', 'blogimages/Old_and_New_2048.webp', 'static', '🚲 Ich fahre kein eBike. Aber ich verstehe jeden, der es tut.', 1, '2026-05-07', '2026-05-07T00:00:00.000Z', '2026-05-07T00:00:00.000Z');

INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content_raw, content_html, category, seo_desc, image_key, image_source, image_alt, published, date, created_at, updated_at)
VALUES ('post_1778040228427', 'fahrradgeschaeft-eroeffnen-was-ich-wirklich-gelernt-habe', '🚲 Fahrradgeschäft eröffnen – was ich wirklich gelernt habe', 'Ein eigenes Fahrradgeschäft aus purer Leidenschaft – klingt nach Traumjob. Ich habe es gemacht, 5 Jahre durchgehalten und dabei mehr gelernt als erwartet. Hier sind meine drei ehrlichsten Erkenntnisse aus dem Bike Business.', 'Würde ich "FEINSCHLIFF BIKES 2.0" eröffnen und mich noch einmal mit einem Fahrradgeschäft selbstständig machen?

Diese Frage ist leicht beantwortet. Nein! Aber das Warum könnte interessant für Dich sein.

Als ich im Jahre 2010 mein erstes Fahrradgeschäft eröffnet habe, war es für mich nicht weniger als pure Leidenschaft. Mein Ziel war es, bis zu meinem 30sten Lebensjahr selbstständig zu werden, mit dem was ich am besten konnte eine Lücke zu schließen und damit mein eigenes Geld zu verdienen.

Selbst etwas zu erschaffen und für den Erfolg meines Geschäftes verantwortlich zu sein, ist ein tolles Gefühl. Niemand, vor dem ich mich rechtfertigen muss. Niemand, dem ich es recht machen musste. Das war toll.

In meinen 5 Jahren FEINSCHLIFF BIKES und in den Jahren danach, habe ich aber auch sehr viel gelernt. Über mich. Über meine Kunden und über mein Business.

Und hier sind meine TOP3 learnings:
⚠️ Ein Business aus einer Leidenschaft heraus zu gründen wird fast immer zum Erfolg. Doch genau diese Leidenschaft stellt sich dann auch vor Effizienz und Wachstum.

⚠️ Im Handel zu arbeiten ist nicht zu unterschätzen. Entweder müsste ich mich bewusst dazu entscheiden, Personal zu beschäftigen, was bedeutet... dass der Service nicht mehr meinen persönlichen Vorstellungen entsprechen könnte, oder ich müsste erneut eine "One-Man-Show" aufführen. Was auch keine Option wäre.

⚠️ Nach 25 Jahren Bike Business, kenne ich die Verpflichtungen, Margen, und die Erwartungen. Egal ob von Seiten der Kunden oder der Lieferanten. Lass mich all das zusammenfassen: "Das Bike Business ist kein Zuckerschlecken". Es hat mich glücklich gemacht. Doch reich wird man bei einer "One-Man-Show" nicht.', '<p>Würde ich &quot;FEINSCHLIFF BIKES 2.0&quot; eröffnen und mich noch einmal mit einem Fahrradgeschäft selbstständig machen?</p>
<p>Diese Frage ist leicht beantwortet. Nein! Aber das Warum könnte interessant für Dich sein.</p>
<p>Als ich im Jahre 2010 mein erstes Fahrradgeschäft eröffnet habe, war es für mich nicht weniger als pure Leidenschaft. Mein Ziel war es, bis zu meinem 30sten Lebensjahr selbstständig zu werden, mit dem was ich am besten konnte eine Lücke zu schließen und damit mein eigenes Geld zu verdienen.</p>
<p>Selbst etwas zu erschaffen und für den Erfolg meines Geschäftes verantwortlich zu sein, ist ein tolles Gefühl. Niemand, vor dem ich mich rechtfertigen muss. Niemand, dem ich es recht machen musste. Das war toll.</p>
<p>In meinen 5 Jahren FEINSCHLIFF BIKES und in den Jahren danach, habe ich aber auch sehr viel gelernt. Über mich. Über meine Kunden und über mein Business.</p>
<p>Und hier sind meine TOP3 learnings:<br>⚠️ Ein Business aus einer Leidenschaft heraus zu gründen wird fast immer zum Erfolg. Doch genau diese Leidenschaft stellt sich dann auch vor Effizienz und Wachstum.</p>
<p>⚠️ Im Handel zu arbeiten ist nicht zu unterschätzen. Entweder müsste ich mich bewusst dazu entscheiden, Personal zu beschäftigen, was bedeutet... dass der Service nicht mehr meinen persönlichen Vorstellungen entsprechen könnte, oder ich müsste erneut eine &quot;One-Man-Show&quot; aufführen. Was auch keine Option wäre.</p>
<p>⚠️ Nach 25 Jahren Bike Business, kenne ich die Verpflichtungen, Margen, und die Erwartungen. Egal ob von Seiten der Kunden oder der Lieferanten. Lass mich all das zusammenfassen: &quot;Das Bike Business ist kein Zuckerschlecken&quot;. Es hat mich glücklich gemacht. Doch reich wird man bei einer &quot;One-Man-Show&quot; nicht.</p>', 'Erfahrung', '5 Jahre eigenes Fahrradgeschäft – meine 3 ehrlichsten Learnings zu Leidenschaft, Handel und dem harten Alltag als Ein-Mann-Betrieb im Bike Business.', 'blogimages/Schluessel_auf_der_Werkbank_2048.webp', 'static', '🚲 Fahrradgeschäft eröffnen – was ich wirklich gelernt habe', 1, '2026-05-06', '2026-05-06T00:00:00.000Z', '2026-05-06T00:00:00.000Z');

INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content_raw, content_html, category, seo_desc, image_key, image_source, image_alt, published, date, created_at, updated_at)
VALUES ('post_1778039453081', 'fahrrad-technik-mehr-gaenge-mehr-kosten-wer-profitiert', '🚲 Fahrrad-Technik: Mehr Gänge, mehr Kosten – wer profitiert?', 'Mehr Gänge, bessere Bremsen – klingt gut. Aber wer hat dir erklärt, was das wirklich kostet? Ich schaue hinter die Marketingversprechen der Fahrradindustrie und nenne die Dinge beim Namen.', 'Den meisten ist es nicht bewusst. Aber die Situation ist überall und immer die gleiche.

⚠️ Nehmen wir ein älteres Beispiel. Nämlich den Serienwechsel von der 8-fach zur 9-fach Kettenschaltung. Der Handel und die Industrie sagten: mehr Gänge, ein kleineres Ritzel um schneller zu sein und größere Ritzel, um leichter den Berg hinauf zu kommen. Das mag sein. Aber wer merkte kritisch an, dass mehr Gänge auf nahezu der gleichen Kassettenbreite auch schmalere Ritzel, schmalere Kettenblätter und eine schmalere... und damit weniger langlebige Kette bedeuten würde?

⚠️ Oder ein zweites Beispiel. Nehmen wir die Scheibenbremse. Ich war einer von denen, die am längsten an der guten alten V-Brake und auch der Magura HS33 festgehalten haben. Statt auf Scheibenbremse umzurüsten, habe ich mir weichere Bremsbacken aus dem "Bike Trial Sport" besorgt. Weil das Geld knapp war? Vielleicht. In jedem Fall aber war ich mit der Performance meiner Bremsen zufrieden.

Hat Dir irgendwer vorgerechnet, was Scheibenbremsen für Servicekosten verursachen? Was neue Bremsbeläge und Scheiben kosten, wenn sie mal abgebremst sind?

Kennt ihr noch die ersten Formula Scheibenbremsen? Fehleranfälliger ging es zu dieser Zeit nicht... und das Ersetzen der immer wieder verschmierten Beläge war wirklich kein Schnäppchen. Und selbst Jahre später hat Shimano das Meisterstück "BRM485" millionenfach in Umlauf gebracht. Ich habe damals keine Bremse mit mehr Problemen erlebt.

Es werden Dinge erfunden und entwickelt, die augenscheinlich viel besser sind als alles vorher dagewesene. Tatsächlich handelt es sich aber um Entwicklungen, die in erster Linie einen höheren Preis rechtfertigen sollen, mehr Folgekosten für den Kunden und mehr Umsatz für die Werkstätten und Industrie generieren.

So funktioniert das System nun mal. Es geht nicht um das Beste für dich. Sondern um dein Geld.', '<p>Den meisten ist es nicht bewusst. Aber die Situation ist überall und immer die gleiche.</p>
<p>⚠️ Nehmen wir ein älteres Beispiel. Nämlich den Serienwechsel von der 8-fach zur 9-fach Kettenschaltung. Der Handel und die Industrie sagten: mehr Gänge, ein kleineres Ritzel um schneller zu sein und größere Ritzel, um leichter den Berg hinauf zu kommen. Das mag sein. Aber wer merkte kritisch an, dass mehr Gänge auf nahezu der gleichen Kassettenbreite auch schmalere Ritzel, schmalere Kettenblätter und eine schmalere... und damit weniger langlebige Kette bedeuten würde?</p>
<p>⚠️ Oder ein zweites Beispiel. Nehmen wir die Scheibenbremse. Ich war einer von denen, die am längsten an der guten alten V-Brake und auch der Magura HS33 festgehalten haben. Statt auf Scheibenbremse umzurüsten, habe ich mir weichere Bremsbacken aus dem &quot;Bike Trial Sport&quot; besorgt. Weil das Geld knapp war? Vielleicht. In jedem Fall aber war ich mit der Performance meiner Bremsen zufrieden.</p>
<p>Hat Dir irgendwer vorgerechnet, was Scheibenbremsen für Servicekosten verursachen? Was neue Bremsbeläge und Scheiben kosten, wenn sie mal abgebremst sind?</p>
<p>Kennt ihr noch die ersten Formula Scheibenbremsen? Fehleranfälliger ging es zu dieser Zeit nicht... und das Ersetzen der immer wieder verschmierten Beläge war wirklich kein Schnäppchen. Und selbst Jahre später hat Shimano das Meisterstück &quot;BRM485&quot; millionenfach in Umlauf gebracht. Ich habe damals keine Bremse mit mehr Problemen erlebt.</p>
<p>Es werden Dinge erfunden und entwickelt, die augenscheinlich viel besser sind als alles vorher dagewesene. Tatsächlich handelt es sich aber um Entwicklungen, die in erster Linie einen höheren Preis rechtfertigen sollen, mehr Folgekosten für den Kunden und mehr Umsatz für die Werkstätten und Industrie generieren.</p>
<p>So funktioniert das System nun mal. Es geht nicht um das Beste für dich. Sondern um dein Geld.</p>', 'Technik', '9-fach Schaltung, Scheibenbremsen, steigende Servicekosten – wer profitiert wirklich von neuer Fahrrad-Technik? Ein ehrlicher Blick hinter die Kulissen.', 'blogimages/Hias_schraubt_in_der_Werkstatt_2048.webp', 'static', '🚲 Fahrrad-Technik: Mehr Gänge, mehr Kosten – wer profitiert?', 1, '2026-05-06', '2026-05-06T00:00:00.000Z', '2026-05-06T00:00:00.000Z');

INSERT OR IGNORE INTO posts (id, slug, title, excerpt, content_raw, content_html, category, seo_desc, image_key, image_source, image_alt, published, date, created_at, updated_at)
VALUES ('post_1778038636607', 'die-schmutzige-meisterpruefung-die-mich-stolz-machte', '🚲 Die schmutzige Meisterprüfung die mich stolz machte.', 'Speichen ablassen, Felge richten, neu spannen – alles von Hand. So sieht echtes Laufrad-Zentrieren aus. Aus meiner Zeit in Berlin. 🔧', 'Ich war in der Fahrradwerkstatt von "Velo Sport Werner Otto" in Berlin. Jung. Hoch motiviert. Und bereit zu zeigen was ich drauf hatte.

Dann kam eine Kundin die Kellertreppe hinunter. Mit einem Hinterrad unter dem Arm, dass definitiv seine besten Zeiten hinter sich hatte. Doch für mich konnte die Herausforderung gar nicht groß genug sein. Auch wenn ich mir die größte Mühe geben musste, die Dame nicht einfach weiterzuschicken.

Aber ich war neu bei Werner Otto und wollte meinem Mechanikerkollegen "Oskar", und auch mir selbst zeigen was ich konnte. Also Augen zu und durch.

"Einmal reinigen und zentrieren" bedeutete in diesem Fall: Grundwäsche. Speichenspannung komplett ablassen. Felge gerade biegen. Laufrad komplett neu spannen und zentrieren. Ich habe das Ding wieder in Form gebracht. Richtig gut sogar.

Interessiert hat sich für mein Meisterwerk dann aber niemand mehr als ich selbst. Schade eigentlich. 😄

🔧 #Radlhias #Fahrradwerkstatt #Mechanikerleben #Berlin #radlhiastv', '<p>Ich war in der Fahrradwerkstatt von &quot;Velo Sport Werner Otto&quot; in Berlin. Jung. Hoch motiviert. Und bereit zu zeigen was ich drauf hatte.</p>
